let tabs;
for(let i=0;i<60;i++){try{tabs=await(await fetch('http://127.0.0.1:9333/json')).json();break;}catch{await new Promise(r=>setTimeout(r,250));}}
ws=new WebSocket(tabs[0].webSocketDebuggerUrl);
await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){pending.get(m.id)?.(m);pending.delete(m.id);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,m=>m.error?reject(m.error):resolve(m.result));ws.send(JSON.stringify({id:n,method,params}));});
await send('Page.enable');
