  const data=JSON.parse(result.result.value);
  if(data.scroll>width||data.overflow.length)failures.push({page,width,...data});
  if(width===375&&page==='index.html'){const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});fs.writeFileSync(path.join(os.tmpdir(),'lawfirm-mobile.png'),Buffer.from(shot.data,'base64'));}
 }
}
console.log(JSON.stringify({checks:56,failures,screenshot:path.join(os.tmpdir(),'lawfirm-mobile.png')},null,2));
await send('Browser.close');
}finally{ws?.close();browser.kill();}
})().catch(e=>{console.error(e);process.exitCode=1});
